export class ParseError extends Error {
  constructor(line, msg) {
    super(msg)
    this.line = line
  }
}

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/
const num = (s) => Number(s.replace(/_/g, ''))
const newTable = () => ({ t: 'table', m: new Map(), hdr: false })

class LineParser {
  constructor(s, line) {
    this.s = s
    this.i = 0
    this.line = line
  }
  err(m) {
    throw new ParseError(this.line, m)
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  get c() {
    return this.s[this.i]
  }
  atEnd() {
    const c = this.c
    return c === undefined || c === '#' || c === ';'
  }
  str(q) {
    // this.i at opening quote
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) this.err('unterminated string')
      this.i++
      if (c === q) return out
      if (c !== '\\' || q === "'") {
        out += c
        continue
      }
      const e = this.c
      if (e === undefined) this.err('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.substr(this.i, 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.err('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        this.err(`invalid escape \\${cp}`)
      }
    }
  }
  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.str(c)
    const st = this.i
    while (isBare(this.c)) this.i++
    if (st === this.i) this.err('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c !== '.') {
        this.i = save
        return parts
      }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }
  value(path) {
    this.ws()
    const c = this.c
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') this.err('expected a value')
    if (c === '"') return { t: 'string', v: this.str('"') }
    if (c === "'") return { t: 'string', v: this.str("'") }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true') return { t: 'boolean', v: true }
    if (tok === 'false') return { t: 'boolean', v: false }
    if (INT.test(tok)) return { t: 'integer', v: num(tok) }
    if (FLOAT.test(tok)) return { t: 'float', v: num(tok) }
    this.err(`invalid value ${tok}`)
  }
  array(path) {
    this.i++
    const items = []
    this.ws()
    if (this.c === ']') {
      this.i++
      return { t: 'array', items, aot: false }
    }
    for (;;) {
      this.ws()
      if (this.atEnd() && this.c !== '#' && this.c !== ';') this.err('unterminated array')
      items.push(this.value(path))
      this.ws()
      if (this.c === ',') {
        this.i++
        this.ws()
        if (this.c === ']') {
          this.i++
          break
        }
        if (this.c === undefined) this.err('unterminated array')
        continue
      }
      if (this.c === ']') {
        this.i++
        break
      }
      this.err('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.err('unterminated inline table')
      this.pair(tbl, path, true)
      this.ws()
      if (this.c === ',') {
        this.i++
        continue
      }
      if (this.c === '}') {
        this.i++
        return tbl
      }
      this.err('unterminated inline table')
    }
  }
  pair(tbl, prefix, inInline) {
    const parts = this.dotted()
    this.ws()
    if (this.c !== '=') this.err(inInline ? 'expected = in an inline table' : 'expected key = value')
    this.i++
    const full = [...prefix, ...parts]
    const v = this.value(full)
    assign(this, tbl, prefix, parts, v)
  }
}

function assign(p, tbl, prefix, parts, v) {
  let t = tbl
  const path = [...prefix]
  for (let k = 0; k < parts.length - 1; k++) {
    const key = parts[k]
    path.push(key)
    let n = t.m.get(key)
    if (n === undefined) {
      n = newTable()
      t.m.set(key, n)
    } else if (n.t === 'array' && n.aot) {
      n = n.items[n.items.length - 1]
    } else if (n.t !== 'table') p.err(`${path.join('.')} is not a table`)
    t = n
  }
  const last = parts[parts.length - 1]
  path.push(last)
  if (t.m.has(last)) p.err(`key ${path.join('.')} is defined twice`)
  t.m.set(last, v)
}

function header(p, root) {
  p.i++
  const aot = p.c === '['
  if (aot) p.i++
  p.ws()
  const parts = p.dotted()
  p.ws()
  const close = () => {
    if (p.c !== ']') p.err('unterminated table header')
    p.i++
  }
  close()
  if (aot) close()
  p.ws()
  if (!p.atEnd()) p.err('trailing text after a table header')
  let t = root
  const path = []
  for (let k = 0; k < parts.length - 1; k++) {
    path.push(parts[k])
    let n = t.m.get(parts[k])
    if (n === undefined) {
      n = newTable()
      t.m.set(parts[k], n)
    } else if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') p.err(`${path.join('.')} is not a table`)
    t = n
  }
  const last = parts[parts.length - 1]
  path.push(last)
  const n = t.m.get(last)
  const ps = path.join('.')
  if (aot) {
    const fresh = newTable()
    if (n === undefined) t.m.set(last, { t: 'array', items: [fresh], aot: true })
    else if (n.t === 'array' && n.aot) n.items.push(fresh)
    else p.err(`${ps} is not an array of tables`)
    return { cur: fresh, path }
  }
  if (n === undefined) {
    const nt = newTable()
    nt.hdr = true
    t.m.set(last, nt)
    return { cur: nt, path }
  }
  if (n.t !== 'table') p.err(`${ps} is not a table`)
  if (n.hdr) p.err(`table ${ps} is defined twice`)
  n.hdr = true
  return { cur: n, path }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((s, idx) => {
    const p = new LineParser(s, idx + 1)
    p.ws()
    if (p.c === undefined || p.c === '#' || p.c === ';') return
    if (p.c === '[') {
      const r = header(p, root)
      cur = r.cur
      curPath = r.path
      return
    }
    p.pair(cur, curPath, false)
    p.ws()
    if (!p.atEnd()) p.err('trailing text after a value')
  })
  return root
}
