  L.ws()
  const ch = L.c
  if (ch === '"') return parseBasic(L)
  if (ch === "'") return parseLiteral(L)
  const st = L.i
  while (L.i < L.s.length && BARE.test(L.s[L.i])) L.i++
  if (L.i === st) fail('expected a name')
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const parts = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c === '.') {
      L.i++
      parts.push(parseName(L))
    } else {
      L.i = save
      return parts
    }
