  L.ws()
  if (L.atEnd()) fail('expected a value')
  const ch = L.c
  if (ch === ',' || ch === ']' || ch === '}') fail('expected a value')
  if (ch === '"') return { t: 'string', v: parseBasic(L) }
  if (ch === "'") return { t: 'string', v: parseLiteral(L) }
  if (ch === '[') {
    L.i++
    const items = []
    let first = true
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated array')
      if (L.c === ']') {
        L.i++
        break
      }
      items.push(parseValue(L, prefix))
      first = false
      L.ws()
