/** Walk through `parts` below `tbl`, creating tables; returns the final table. */
function walk(tbl, parts, prefix) {
  let cur = tbl
  for (let k = 0; k < parts.length; k++) {
    const name = parts[k]
    const ex = cur.map.get(name)
    if (!ex) {
      const n = newTable()
      cur.map.set(name, n)
      cur = n
    } else if (ex.t === 'table') {
      cur = ex
    } else if (ex.t === 'array' && ex.tables) {
      cur = ex.items[ex.items.length - 1]
    } else {
