  L.ws()
  if (!L.atEnd()) fail(msg)
}

function parseHeader(L, root) {
  const array = L.s[L.i + 1] === '['
  L.i += array ? 2 : 1
  const parts = parseDotted(L)
  L.ws()
  const close = array ? ']]' : ']'
