import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.pos = pos
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isWord = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1
  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (pos, reason) => { throw new ScanError(pos, reason) }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const pos = { line, col }
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) fail(pos, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      continue
    }
    const pos = { line, col }
    const emit = (kind, body) => tokens.push({ pos, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let s = ''
      while (true) {
        if (i >= n) fail(pos, 'unterminated string')
        const d = adv()
        if (d === '"') break
        s += d
      }
      emit('rawstring', JSON.stringify(s))
      continue
    }
    if (isLetter(c) || c === '_') {
      let s = ''
      while (i < n && isWord(cs[i])) s += adv()
      emit(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const run = (ok) => {
        if (!ok(cs[i])) return false
        s += adv()
        while (i < n) {
          if (ok(cs[i])) s += adv()
          else if (cs[i] === '_' && ok(cs[i + 1])) { s += adv(); s += adv() }
          else break
        }
        return true
      }
      let bad = false
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        s += adv(); s += adv()
        const ok = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1]
          if (isDigit(a)) { s += adv(); run(isDigit) }
          else if ((a === '+' || a === '-') && isDigit(cs[i + 2])) { s += adv(); s += adv(); run(isDigit) }
        }
      }
      if (bad || isWord(cs[i])) {
        while (i < n && isWord(cs[i])) s += adv()
        fail(pos, `invalid number ${s}`)
      }
      emit('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let s = ''
      while (true) {
        if (i >= n) fail(pos, 'unterminated string')
        const bpos = { line, col }
        const d = cs[i]
        if (d === '\n') fail(bpos, 'newline in string')
        adv()
        if (d === '"') break
        if (d !== '\\') { s += d; continue }
        if (i >= n) fail(pos, 'unterminated string')
        const e = cs[i]
        const bad = () => fail(bpos, `invalid escape \\${e}`)
        if (e === '\n') fail({ line, col }, 'newline in string')
        adv()
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) s += simple[e]
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) bad()
          s += String.fromCodePoint(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) bad()
          while (i <= j) adv()
          s += String.fromCodePoint(v)
        } else bad()
      }
      emit('string', JSON.stringify(s))
      continue
    }
    if (i + 1 < n && PUNCT2.includes(c + cs[i + 1])) {
      adv(); adv()
      emit('punct', c + cs[i - 1 + 0] === undefined ? '' : cs[i - 2] + cs[i - 1])
      continue
    }
    if (PUNCT1.includes(c)) { adv(); emit('punct', c); continue }
    fail(pos, `unexpected character ${c}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0, 'utf8')
  let tokens
  try {
    tokens = scan(text)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.pos.line}:${t.pos.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

