const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let exhausted = 0n
    for (const b of ballots) {
      const pick = b.names.find((n) => continuing.has(n))
      if (pick === undefined) exhausted += b.count
      else { votes.get(pick) ; votes.set(pick, votes.get(pick) + b.count); active += b.count }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const listing = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : cmp(a[0], b[0])))
    const round = { listing, exhausted, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = listing[0]
    if (top[1] * 2n > active) return { rounds, winner: top[0] }
    const min = listing[listing.length - 1][1]
    let tied = listing.filter(([, v]) => v === min).map(([c]) => c)
    while (tied.length > 1) {
      let k = 0
      for (; k < rounds.length; k++) {
        const vs = tied.map((c) => history.get(c)[k])
        if (vs.some((v) => v !== vs[0])) {
          const m = vs.reduce((a, b) => (b < a ? b : a))
          tied = tied.filter((c, j) => vs[j] === m)
          break
        }
      }
      if (k === rounds.length) break
    }
    const out = tied.reduce((a, b) => (b > a ? b : a))
    round.eliminated = out
    continuing.delete(out)
  }
}
