      if (wi < 0) break
      let best = null
      for (const k of names) {
        if (done.has(k)) continue
        if (!dl.get(k).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      const f = t + cost.get(best)
      done.set(best, f)
      busy[wi] = f
      ran[wi].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const b of busy) if (b > t && (next === null || b < next)) next = b
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
