const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const run = (ok) => {
        // digit (digit | _ digit)*; returns count of digits consumed
        let k = 0
        if (!ok(cs[i])) return 0
        s += adv(); k++
        while (i < n) {
          if (ok(cs[i])) { s += adv(); k++ }
          else if (cs[i] === '_' && ok(cs[i + 1])) { s += adv(); s += adv(); k++ }
          else break
        }
        return k
      }
      let bad = false
      const p = cs[i + 1]
      let radixOk = null
      if (c === '0' && (p === 'x' || p === 'X')) radixOk = isHex
      else if (c === '0' && (p === 'b' || p === 'B')) radixOk = (d) => d === '0' || d === '1'
      else if (c === '0' && (p === 'o' || p === 'O')) radixOk = (d) => d !== undefined && d >= '0' && d <= '7'
      if (radixOk) {
        s += adv(); s += adv()
        if (run(radixOk) === 0) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
        const e = cs[i]
        if (e === 'e' || e === 'E') {
          const q = cs[i + 1]
          if (isDigit(q) || ((q === '+' || q === '-') && isDigit(cs[i + 2]))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            run(isDigit)
          }
        }
      }
      if (i < n && isIdPart(cs[i])) bad = true
      if (bad) {
        while (i < n && isIdPart(cs[i])) s += adv()
