    const fail = (m) => new UriError(`line ${n}: ${m}`)
    try {
      if (mode === 'normalize') {
        results.push(normalize(parse(line)))
      } else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw fail('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === undefined) throw fail('the base has no scheme')
        results.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
