    } catch (e) {
      if (e instanceof UriError && !e.message.startsWith('line ')) throw fail(e.message)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
if (results.length) process.stdout.write(results.join('\n') + '\n')
