const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) { process.stderr.write(msg + '\n'); process.exit(2) }
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

import('node:fs').then(({ readFileSync }) => main(readFileSync(0, 'utf8')))

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let names = null
  const declared = new Set()
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (names) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      names = []
      for (const nm of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
        if (declared.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
        declared.add(nm); names.push(nm)
      }
    } else if (t[0] === 'ballot') {
      if (!names) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const nm of t.slice(2)) {
        if (!declared.has(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
        if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
        seen.add(nm)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  })
  if (!names) fail('error: no candidates')
  return { names, ballots }
}

function main(text) {
  const { names, ballots } = parse(text)
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  const continuing = new Set(names)
  const history = []
  const out = []
  let winner = null
  let k = 0
  for (;;) {
    k++
    const counts = new Map([...continuing].map(c => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find(p => continuing.has(p))
      if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
    }
    history.push(counts)
    const list = [...counts.entries()].sort((a, b) => a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
    out.push(`round ${k}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
    if (active === 0n) break
    const top = list.find(([, v]) => v * 2n > active)
    if (top) { winner = top[0]; break }
    let tied = list.filter(([, v]) => v === list[list.length - 1][1]).map(e => e[0])
    while (tied.length > 1) {
      let changed = false
      for (const h of history) {
        const vals = tied.map(c => h.get(c))
        const min = vals.reduce((a, b) => a < b ? a : b)
        if (vals.some(v => v !== min)) {
          tied = tied.filter(c => h.get(c) === min)
          changed = true
          break
        }
      }
      if (!changed) break
    }
    const elim = tied.reduce((a, b) => a > b ? a : b)
    continuing.delete(elim)
    out.push(`eliminated ${elim}`)
  }
  const end = winner ? `winner ${winner}` : 'no winner'
  const res = mode === 'rounds' ? [...out, end] : [`rounds ${k}`, end]
  process.stdout.write(res.join('\n') + '\n')
}
