function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + (L.charCodeAt(1) - 64) + 0
  const colIdx = L.length === 1 ? col : col // two letters: 27.. offset below
  const c = L.length === 1 ? colIdx : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col: c, row }
}
function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const x = c - 27
  return String.fromCharCode(65 + Math.floor(x / 26)) + String.fromCharCode(65 + (x % 26))
}
const key = (a) => colName(a.col) + a.row

// ---- input
const text = fs.readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
