    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[=<>^*\/+\-(),:])/.exec(src.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
