    'a\n<<<<<<< mine\nX\n=======\nY\n>>>>>>> theirs\nc\n',
  )
})

test('regions classify a clean merge', () => {
  assert.deepEqual(run(['regions'], ['a', 'X'], ['a', 'b'], ['a', 'b']), { code: 0, out: 'stable 1\nmine 1\n', err: '' })
})

