  process.exit(2)
}

function changesOf(base, side) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0
  let j = 0
  let ci = 0
  let cj = 0
  const flush = () => {
    if (i > ci || j > cj) out.push({ bs: ci, be: i, ss: cj, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++
      j++
      ci = i
      cj = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n
  j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [
    ...changesOf(base, mine).map(c => ({ ...c, who: 0 })),
    ...changesOf(base, theirs).map(c => ({ ...c, who: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)

  const out = []
  let conflict = false
  let pos = 0
  const stable = (upto) => {
    if (upto > pos) {
      const seg = base.slice(pos, upto)
      if (mode === 'regions') out.push(`stable ${seg.length}`)
      else out.push(...seg)
    }
  }
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    const baseSeg = base.slice(rs, re)
    const sideLines = (who, doc) => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return baseSeg
      const first = g[0]
      const minBs = Math.min(...g.map(c => c.bs))
      const maxBe = Math.max(...g.map(c => c.be))
      const s = first.ss - (minBs - rs)
      const e = g[g.length - 1].se + (re - maxBe)
      return doc.slice(s, e)
    }
    const mi = sideLines(0, mine)
    const th = sideLines(1, theirs)
    let res
    let label
    if (same(mi, th)) {
      res = mi
      label = group.length === 1 ? (group[0].who === 0 ? 'mine' : 'theirs') : 'both'
      if (group.some(c => c.who === 0) && group.some(c => c.who === 1)) label = 'both'
    } else if (same(mi, baseSeg)) {
      res = th
      label = 'theirs'
    } else if (same(th, baseSeg)) {
      res = mi
      label = 'mine'
    } else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${mi.length} base=${baseSeg.length} theirs=${th.length}`)
      else {
        out.push('<<<<<<< mine', ...mi)
        if (mode === 'merge') out.push('||||||| base', ...baseSeg)
        out.push('=======', ...th, '>>>>>>> theirs')
      }
      continue
    }
    if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  stable(base.length)
  process.stdout.write(out.map(l => `${l}\n`).join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
