  const events = []
  let started = false
  let last = null
  const num = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }
  for (let i = 0; i < lines.length; i++) {
    const text = lines[i].trim()
    if (text === '' || text[0] === '#') continue
    const t = text.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (t.length !== n) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        let p
        if (d === 'bucket') p = { kind: 'bucket', cap: num(t[2], 'capacity', 1), refill: num(t[3], 'refill', 0), per: num(t[4], 'per', 1) }
        else p = { kind: 'window', limit: num(t[2], 'limit', 0), span: num(t[3], 'span', 1) }
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        p.name = t[1]
        p.states = new Map()
        policies.set(t[1], p)
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        const list = []
        for (const n of t.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(t[1], list)
      } else if (d === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num(t[1], 'tick', 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        started = true
        events.push([tick, t[2]])
